{
  "name": "Typhos报警汇总指示组件",
  "name_en": "Typhos Alarm Summary Indicator",
  "manufacturer": "",
  "description": "一个非物理的软件界面组件，用于汇总 Ophyd 设备多个信号的报警与连接状态，并在 Typhos/PyDM 图形控件上用颜色和工具提示显示最严重的报警情况。它适合用于实验控制界面的状态总览和告警提示。",
  "description_en": "A non-physical software UI component that summarizes alarm and connection states from multiple Ophyd device signals, then shows the worst alarm state on Typhos/PyDM graphical widgets using colors and tooltips. It is used for status overview and alarm indication in laboratory control interfaces.",
  "actions": [
    {
      "action_name": "auto-reset_alarm_state",
      "description": "重置当前报警汇总状态和相关显示。",
      "description_en": "Reset the current summarized alarm state and related display state."
    },
    {
      "action_name": "auto-channels",
      "description": "返回此报警组件使用的 PyDM 通道列表。",
      "description_en": "Return the list of PyDM channels used by this alarm component."
    },
    {
      "action_name": "auto-add_device",
      "description": "将设备加入报警汇总监视。",
      "description_en": "Add a device to the alarm summary monitoring."
    },
    {
      "action_name": "auto-clear_all_alarm_configs",
      "description": "清除全部报警监视配置并恢复到未配置状态。",
      "description_en": "Clear all alarm monitoring configurations and return to an unconfigured state."
    },
    {
      "action_name": "auto-setup_alarm_config",
      "description": "根据设备信号和 kind 级别建立报警汇总配置。",
      "description_en": "Set up alarm summary configuration based on device signals and the selected kind level."
    },
    {
      "action_name": "auto-update_alarm_config",
      "description": "在设置变化后重建报警配置。",
      "description_en": "Rebuild the alarm configuration after settings change."
    },
    {
      "action_name": "auto-update_connection",
      "description": "更新指定通道的连接或断连状态。",
      "description_en": "Update the connected or disconnected state of a specified channel."
    },
    {
      "action_name": "auto-update_severity",
      "description": "更新指定通道的报警严重度。",
      "description_en": "Update the alarm severity of a specified channel."
    },
    {
      "action_name": "auto-update_current_alarm",
      "description": "重新计算当前最严重的汇总报警状态。",
      "description_en": "Recalculate the current worst summarized alarm state."
    },
    {
      "action_name": "auto-set_alarm_color",
      "description": "根据报警级别设置控件显示颜色。",
      "description_en": "Set the widget display color according to the alarm level."
    },
    {
      "action_name": "auto-eventFilter",
      "description": "处理界面事件以支持报警提示和交互行为。",
      "description_en": "Handle UI events to support alarm indication and interaction behavior."
    },
    {
      "action_name": "auto-show_alarm_tooltip",
      "description": "显示包含报警或断连通道信息的工具提示。",
      "description_en": "Show a tooltip with information about alarmed or disconnected channels."
    },
    {
      "action_name": "auto-kindLevel",
      "description": "获取或设置纳入报警汇总的信号 kind 级别。",
      "description_en": "Get or set the signal kind level included in the alarm summary."
    },
    {
      "action_name": "auto-channel",
      "description": "获取或设置此组件使用的通道地址。",
      "description_en": "Get or set the channel address used by this component."
    },
    {
      "action_name": "auto-alarm",
      "description": "获取当前汇总报警级别。",
      "description_en": "Get the current summarized alarm level."
    },
    {
      "action_name": "auto-describe",
      "description": "返回此报警组件的描述信息。",
      "description_en": "Return descriptive information about this alarm component."
    }
  ],
  "tag_hints": [
    "Typhos UI",
    "PyDM alarm indicator",
    "Ophyd device alarms",
    "alarm summary",
    "GUI status widget",
    "EPICS PV connectivity",
    "tooltip alarm display"
  ]
}

